/* Lesson 01 labs (Strings). Part of the course scripts: every Java page loads course-index.js, quiz-data.js, course.js,
   effects.js, then the labs of the lesson, then run-java.js. Classic scripts share one global scope, so nothing here is a
   top-level name: everything lives inside one IIFE. course.js provides $, $$, esc, hl, store, cells and the Java-imitation
   helpers (JavaEx, jstr, jarr, idx, jsplit, jrepl, jcompare, jstrip, jtrim). The String pool stepper (#poolviz) and the
   [data-cells] boxes are core widgets in course.js; this file holds the analogy visuals and the String methods playground
   (#smPlay, classes sm-, test hook window.SMX). Hosts are .viz.an[id]; each builder is guarded by its id. */
"use strict";
(function(){
  if(!$(".an[id]"))return;
  const still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  const pop=el=>{if(el&&!still)el.animate([{transform:"scale(.6)",opacity:0},{transform:"scale(1.08)",opacity:1,offset:.7},{transform:"none",opacity:1}],{duration:450,easing:"cubic-bezier(.2,1.4,.4,1)"});};
  const head=(t,sub,hooks)=>'<div class="ol-head an-h"><b>'+t+"</b><span>"+sub+"</span></div>"+(hooks?'<div class="an-hooks">'+hooks.map(h=>"<span>"+h+"</span>").join("")+"</div>":"");
  const mount=(id,title,sub,hooks,body)=>{const h=$("#"+id);if(!h)return null;h.innerHTML=head(title,sub,hooks)+'<div class="vbody">'+body+'<div class="an-foot"></div></div>';return h;};

  /* ===== identical twins: == vs equals ===== */
  (function(){const h=mount("anTwins","Identical twins","== asks \"same person?\"  equals asks \"same name?\"",
      ["<b>==</b> = is it the <b>same person</b>?","<b>equals</b> = do they <b>say the same name</b>?","two <code>new String(\"Asha\")</code> = twins","a second variable = a nickname for one person"],
      '<div class="an-people"></div><div class="ol-cmds"><button type="button" class="chip" data-q="eq">a == b</button><button type="button" class="chip" data-q="equals">a.equals(b)</button><button type="button" class="chip" data-q="alias">String c = a;  a == c</button><button type="button" class="chip" data-q="lit">two literals: "Asha" == "Asha"</button></div>');
    if(!h)return;
    $(".an-foot",h).innerHTML='<div class="an-code"></div><div class="msg" aria-live="polite">Two Strings made with <code>new String("Asha")</code> are identical twins: same name, two different people. Ask a question.</div>';
    const P=(tags,name,cls)=>'<div class="an-person '+(cls||"")+'"><div class="an-face">🧑</div><b>"'+name+'"</b><div class="an-tags">'+tags.map(t=>"<span>"+t+"</span>").join("")+"</div></div>";
    const draw=m=>{$(".an-people",h).innerHTML=m==="alias"?P(["a","c"],"Asha","hot")+P(["b"],"Asha"):m==="lit"?P(["x","y"],"Asha","hot")+'<div class="an-note">one pooled String: both literals share it</div>':P(["a"],"Asha",m==="eq"?"hot":m==="equals"?"talk":"")+P(["b"],"Asha",m==="eq"?"hot":m==="equals"?"talk":"");};
    const Q={eq:["a == b   // false","<code>==</code> compares <b>who</b>: two different people, so <b>false</b>, even though they look the same."],
      equals:["a.equals(b)   // true","<code>equals</code> compares <b>what they say</b>: both say \"Asha\", so <b>true</b>. Use this for Strings."],
      alias:["String c = a;   a == c   // true","<code>c</code> is just a nickname tag on the <b>same</b> person, so <code>a == c</code> is <b>true</b>."],
      lit:['"Asha" == "Asha"   // true (pooled)',"Literals go in the String pool, so both are the <b>same</b> person and <code>==</code> happens to be true. Don't rely on it: compare text with <code>equals</code>."]};
    h.addEventListener("click",e=>{const b=e.target.closest("[data-q]");if(!b)return;const q=b.dataset.q;$$("[data-q]",h).forEach(x=>x.classList.toggle("on",x===b));draw(q);
      $(".an-code",h).innerHTML='<div class="cur">'+hl(Q[q][0])+"</div>";$(".msg",h).innerHTML=Q[q][1];$$(".an-person.hot,.an-person.talk",h).forEach(pop);});
    draw("");})();

  /* ===== the sticker book: how the String pool decides ===== */
  (function(){const h=mount("anBook","The sticker book","Every literal is a sticker. The pool is the one shared book: same text, same sticker.",
      ["a <b>literal</b> = look in the book first","<b>new</b> = print your own copy, never in the book","<b>intern()</b> = hand your copy to the book","immutability makes sharing safe"],
      '<div class="an-people" id="anBookRow"></div><div class="ol-cmds"><button type="button" class="chip" data-b="lit">String a = "car";</button><button type="button" class="chip" data-b="lit2">String b = "car";</button><button type="button" class="chip" data-b="new">String c = new String("car");</button><button type="button" class="chip" data-b="intern">String d = c.intern();</button><button type="button" class="chip" data-b="reset">Reset</button></div>');
    if(!h)return;
    $(".an-foot",h).innerHTML='<div class="an-code"></div><div class="msg" aria-live="polite">Press the statements in order and watch where each variable points.</div>';
    let book=[],copies=[],log=[];
    const card=(tags,name,cls,where)=>'<div class="an-person '+(cls||"")+'"><div class="an-face">'+(where==="book"?"📖":"🖨️")+'</div><b>"'+name+'"</b><div class="an-tags">'+tags.map(t=>"<span>"+t+"</span>").join("")+'</div><div class="an-note">'+(where==="book"?"in the sticker book (pool)":"a private copy (heap)")+"</div></div>";
    const draw=hot=>{const row=$("#anBookRow",h);row.innerHTML=book.map(s=>card(s.tags,s.t,hot===s?"hot":"","book")).join("")+copies.map(s=>card(s.tags,s.t,hot===s?"hot":"","copy")).join("")||'<div class="an-note">the book is empty</div>';
      $(".an-code",h).innerHTML=log.map((l,i)=>'<div class="'+(i===log.length-1?"cur":"")+'">'+hl(l)+"</div>").join("")||'<div class="dim">// press a statement</div>';pop($(".an-person.hot",h));};
    const M={lit:()=>{let s=book.find(x=>x.t==="car");const was=!!s;if(!s){s={t:"car",tags:[]};book.push(s);}if(!s.tags.includes("a"))s.tags.push("a");log.push('String a = "car";');
        $(".msg",h).innerHTML=was?'The book already has <code>"car"</code>, so <code>a</code> gets that sticker.':'<code>"car"</code> is not in the book yet, so one sticker is <b>added</b> and <code>a</code> points to it.';return s;},
      lit2:()=>{let s=book.find(x=>x.t==="car");const was=!!s;if(!s){s={t:"car",tags:[]};book.push(s);}if(!s.tags.includes("b"))s.tags.push("b");log.push('String b = "car";');
        $(".msg",h).innerHTML=was?'Same text, same sticker: <code>b</code> points to the <b>same</b> object as <code>a</code>, so <code>a == b</code> is true.':'<code>"car"</code> was not in the book yet, so it is added now and <code>b</code> points to it.';return s;},
      new:()=>{const s={t:"car",tags:["c"]};copies.push(s);log.push('String c = new String("car");');
        $(".msg",h).innerHTML='<code>new</code> prints a <b>private copy</b>: same text, different object, never in the book. <code>a == c</code> is false, <code>a.equals(c)</code> is true.';return s;},
      intern:()=>{let s=book.find(x=>x.t==="car");const was=!!s;if(!s){s={t:"car",tags:[]};book.push(s);}if(!s.tags.includes("d"))s.tags.push("d");log.push("String d = c.intern();");
        $(".msg",h).innerHTML=was?'<code>intern()</code> looks the text up in the book and returns the <b>book\'s</b> sticker, so <code>d == a</code> is true. The private copy <code>c</code> stays where it is.':'The book had no <code>"car"</code>, so <code>intern()</code> puts <b>this</b> text in and returns it.';return s;},
      reset:()=>{book=[];copies=[];log=[];$(".msg",h).innerHTML="Press the statements in order and watch where each variable points.";return null;}};
    h.addEventListener("click",e=>{const b=e.target.closest("[data-b]");if(!b)return;draw(M[b.dataset.b]());});
    draw(null);})();

  /* ===== String methods playground (#smPlay): every common String method, live, explained =====
     The text box and every String argument are the BODY of a Java literal, so \n \t \" \\ and \uXXXX work and an unknown
     escape is the compile error javac gives. Each method entry: c (group), n (name), sig, since (Java version), s (sample
     text), args [[name, type(int|String|char|any), default]], run(s, args) → {r: display text, t: Java type, out?: String
     result, list?: array result, hl?: [[from, to, state]] marks on s, why: explanation HTML}, tip, iv (interview line),
     decl (variable name in the code preview), st (static: not called on s). Results are checked against JDK 25
     (see kb/lesson-01-strings.md → section 8). */
  (function(){
    const host=$("#smPlay");if(!host)return;
    const E=esc;
    const show=s=>s.replace(/\\/g,"\\\\").replace(/\n/g,"\\n").replace(/\t/g,"\\t").replace(/\r/g,"\\r").replace(/"/g,'\\"');
    const lit=s=>'"'+show(s)+'"';
    const unesc=t=>t.replace(/\\(u[0-9A-Fa-f]{4}|.|$)/g,(m,c)=>{if(c==="n")return"\n";if(c==="t")return"\t";if(c==="r")return"\r";if(c==="\\")return"\\";if(c==='"')return'"';if(c==="'")return"'";if(c[0]==="u")return String.fromCharCode(parseInt(c.slice(1),16));
      throw new JavaEx("compile error","illegal escape character in String literal: \\"+c);});
    const enc=new TextEncoder();
    const fold=c=>c.toUpperCase().toLowerCase();
    const foldS=s=>s.split("").map(c=>fold(c).length===1?fold(c):c).join("");
    const jlines=s=>{if(s==="")return[];const a=s.split(/\r\n|\r|\n/);if(a.length&&a[a.length-1]===""&&/[\r\n]$/.test(s))a.pop();return a;};
    const plural=(n,w)=>n+" "+w+(n===1?"":"s");
    const range=(a,b,st)=>[[a,b,st||"read"]];
    const posOf=(s,x,i)=>i>=0?'found at index <b>'+i+'</b>'+(x.length>1?' (it occupies '+i+'–'+(i+x.length-1)+')':''):'<b>not found</b>, so the answer is <b>-1</b>';
    const NEW='<span class="sm-new">new String object</span>';
    /* an "any" argument is typed the way javac would type it */
    const anyArg=t=>{const v=t.trim();if(/^-?\d+$/.test(v))return{k:"int",v:+v,src:v};if(/^-?\d*\.\d+$/.test(v))return{k:"double",v:+v,src:v};if(v==="true"||v==="false")return{k:"boolean",v:v==="true",src:v};const s=unesc(t);return{k:"String",v:s,src:lit(s)};};
    const group=(v,fl)=>{const neg=v.startsWith("-"),d=neg?v.slice(1):v;const [i,f]=d.split(".");return (neg?"-":"")+(fl.includes(",")?i.replace(/\B(?=(\d{3})+(?!\d))/g,","):i)+(f!=null?"."+f:"");};
    const fmt=(f,arg)=>{let used=0;const out=f.replace(/%([-0,+ #]*)(\d+)?(?:\.(\d+))?([sSdfnxXcbB%])/g,(m,fl,w,p,c)=>{
      if(c==="n")return"\n";if(c==="%")return"%";if(used++)throw new JavaEx("MissingFormatArgumentException","Format specifier '"+m+"'");let v;const bad=()=>{throw new JavaEx("IllegalFormatConversionException",c+" != java.lang."+(arg.k==="int"?"Integer":arg.k==="double"?"Double":arg.k==="boolean"?"Boolean":"String"));};
      if(c==="s"||c==="S"){v=String(arg.v);if(p!=null)v=v.slice(0,+p);if(c==="S")v=v.toUpperCase();}
      else if(c==="d"){if(arg.k!=="int")bad();v=group(String(arg.v),fl);if(fl.includes("+")&&arg.v>=0)v="+"+v;else if(fl.includes(" ")&&arg.v>=0)v=" "+v;}
      else if(c==="f"){if(arg.k!=="int"&&arg.k!=="double")bad();if(arg.k==="int")bad();v=group(arg.v.toFixed(p==null?6:+p),fl);if(fl.includes("+")&&arg.v>=0)v="+"+v;}
      else if(c==="x"||c==="X"){if(arg.k!=="int")bad();v=(arg.v<0?(arg.v>>>0):arg.v).toString(16);if(c==="X")v=v.toUpperCase();}
      else if(c==="c"){if(arg.k==="String"){if(arg.v.length!==1)bad();v=arg.v;}else if(arg.k==="int")v=String.fromCharCode(arg.v);else bad();}
      else if(c==="b"||c==="B"){v=arg.k==="boolean"?String(arg.v):"true";if(c==="B")v=v.toUpperCase();}
      if(w){const n=+w;if(v.length<n){if(fl.includes("-"))v=v.padEnd(n);else if(fl.includes("0")&&/[dfxX]/.test(c)){const neg=/^[-+ ]/.test(v);v=(neg?v[0]:"")+(neg?v.slice(1):v).padStart(n-(neg?1:0),"0");}else v=v.padStart(n);}}
      return v;});
      if(!used&&/%/.test(f.replace(/%[n%]/g,"")))throw new JavaEx("UnknownFormatConversionException","Conversion = '"+(f.match(/%[^sSdfnxXcbB%]?/)||["%"])[0].slice(1)+"'");
      return out;};
    const caseWhy=(s,r,up)=>{const ch=[];for(let i=0;i<s.length;i++)if(s[i]!==r[i])ch.push(i);return{ch,why:ch.length?'<b>'+plural(ch.length,"character")+'</b> changed (marked); digits, spaces and punctuation have no '+(up?"upper":"lower")+' case and stay as they are. The result is a '+NEW+'; <code>s</code> still holds the original text.':'Nothing to change: every character was already '+(up?"upper":"lower")+' case (or has no case). Java then returns <code>s</code> itself instead of copying: an optimisation you can only notice with <code>==</code>.'};};
    const M=[
      /* ---- inspect ---- */
      {c:"inspect",n:"length()",sig:"int length()",s:"Hello, World",decl:"int n",args:[],run:s=>({r:s.length,t:"int",hl:range(0,s.length),why:s.length?'Counts <b>every</b> character, spaces and punctuation included: <b>'+s.length+'</b>. Indexes run from <b>0</b> to <b>'+(s.length-1)+'</b> (always <code>length() - 1</code>).':'The empty String <code>""</code> has <b>0</b> characters. It is a real object, unlike <code>null</code>.'}),
        tip:"Parentheses matter: <code>s.length()</code> for a String, <code>arr.length</code> for an array, <code>list.size()</code> for a collection.",iv:"It is O(1): the count is stored with the object, nothing is scanned."},
      {c:"inspect",n:"isEmpty()",sig:"boolean isEmpty()",s:"",decl:"boolean b",args:[],run:s=>({r:s.length===0,t:"boolean",why:s.length===0?'<b>true</b>: the length is 0. This is the empty String <code>""</code>, which is not the same as <code>null</code>.':'<b>false</b>: there are '+plural(s.length,"character")+(jstrip(s)===""?', even though they are all whitespace. Use <code>isBlank()</code> for that question.':'.')}),
        tip:'<code>"  ".isEmpty()</code> is <b>false</b> (two spaces). Calling <code>isEmpty()</code> on <code>null</code> throws NullPointerException.',iv:"isEmpty: length 0. isBlank: only whitespace. null: no object at all. Three different states."},
      {c:"inspect",n:"isBlank()",sig:"boolean isBlank()",since:11,s:"  \t ",decl:"boolean b",args:[],run:s=>{const t=jstrip(s);let i=0;while(i<s.length&&jws(s.charCodeAt(i)))i++;return{r:t==="",t:"boolean",hl:t===""?range(0,s.length,"cut"):range(i,i+1),why:t===""?'<b>true</b>: '+(s.length?'all '+plural(s.length,"character")+' are whitespace (spaces, tabs, newlines, Unicode spaces).':'it is empty, and empty counts as blank.'):'<b>false</b>: the first non-whitespace character is at index <b>'+i+'</b>.'};},
        tip:"Validate user input with <code>isBlank()</code>, not <code>isEmpty()</code>: a name of three spaces is empty for a human.",iv:"Added in Java 11 together with strip(), repeat() and lines()."},
      {c:"inspect",n:"charAt(int)",sig:"char charAt(int index)",s:"Hello, World",decl:"char c",args:[["index","int","4"]],run:(s,[i])=>{idx(s,i);return{r:"'"+s[i]+"'",t:"char",hl:range(i,i+1),why:'Index <b>'+i+'</b> (counting from 0) holds <b>\''+E(v(s[i]))+'\'</b>. The valid range is 0 to '+(s.length-1)+'.'};},
        err:(s,[i])=>'Index <b>'+i+'</b> does not exist: the valid range is 0 to '+(s.length-1)+'. Java throws at run time; <code>s.charAt(s.length())</code> is the classic off-by-one.',
        tip:"It returns a <code>char</code>, a 16-bit number in disguise: <code>'o' + 1</code> is <b>112</b>, not <code>\"o1\"</code>.",iv:"The last character is charAt(length() - 1); charAt(length()) throws StringIndexOutOfBoundsException."},
      {c:"inspect",n:"hashCode()",sig:"int hashCode()",s:"car",decl:"int h",args:[],run:s=>{let h=0;for(let i=0;i<s.length;i++)h=(Math.imul(31,h)+s.charCodeAt(i))|0;return{r:h,t:"int",hl:range(0,s.length),why:'<code>h = 31 * h + c</code> for every character'+(s.length&&s.length<=6?': '+s.split("").map((c,i)=>c.charCodeAt(0)+(s.length-1-i?" · 31<sup>"+(s.length-1-i)+"</sup>":"")).join(" + ")+' = <b>'+h+'</b>':'')+'. Equal text always gives an equal hash, which is why Strings work as HashMap keys.'};},
        tip:"Different Strings can share a hash (a collision), so a hash can never replace <code>equals</code>.",iv:"The hash is computed once and cached in the object; immutability makes the cache safe."},
      /* ---- search ---- */
      {c:"search",n:"indexOf(String)",sig:"int indexOf(String str)",s:"Hello, World",decl:"int i",args:[["str","String","o"]],run:(s,[x])=>{const i=s.indexOf(x);return{r:i,t:"int",hl:i>=0?range(i,i+x.length):[],why:'Scans left to right; <code>'+E(lit(x))+'</code> is '+posOf(s,x,i)+'.'+(i>=0&&s.indexOf(x,i+1)>=0?' Only the <b>first</b> match counts (there is another at '+s.indexOf(x,i+1)+').':'')};},
        tip:"<b>-1</b> means not found. It is a value, not an exception, so always check for it before <code>substring</code>.",iv:"There is a char overload too: indexOf('o'). Both are O(n) scans."},
      {c:"search",n:"indexOf(String, int)",sig:"int indexOf(String str, int fromIndex)",s:"Hello, World",decl:"int i",args:[["str","String","o"],["fromIndex","int","5"]],run:(s,[x,f])=>{const i=s.indexOf(x,Math.max(0,f));return{r:i,t:"int",hl:[[0,Math.min(Math.max(0,f),s.length),"cut"]].concat(i>=0?range(i,i+x.length):[]),why:'The search starts at index <b>'+f+'</b>; everything before it is ignored. <code>'+E(lit(x))+'</code> is '+posOf(s,x,i)+'.'};},
        tip:"This is how you find the <i>next</i> occurrence in a loop: <code>i = s.indexOf(x, i + 1)</code>.",iv:"A fromIndex past the end simply returns -1; a negative one is treated as 0."},
      {c:"search",n:"lastIndexOf(String)",sig:"int lastIndexOf(String str)",s:"Hello, World",decl:"int i",args:[["str","String","o"]],run:(s,[x])=>{const i=s.lastIndexOf(x);return{r:i,t:"int",hl:i>=0?range(i,i+x.length):[],why:'Scans from the <b>right</b>; the last <code>'+E(lit(x))+'</code> is '+posOf(s,x,i)+'.'};},
        tip:'File extensions: <code>name.substring(name.lastIndexOf(".") + 1)</code>.',iv:"indexOf finds the first match, lastIndexOf the last; both return -1 when absent."},
      {c:"search",n:"contains(CharSequence)",sig:"boolean contains(CharSequence s)",s:"Hello, World",decl:"boolean b",args:[["s","String","World"]],run:(s,[x])=>{const i=s.indexOf(x);return{r:i>=0,t:"boolean",hl:i>=0?range(i,i+x.length):[],why:(i>=0?'<b>true</b>: ':'<b>false</b>: ')+'<code>'+E(lit(x))+'</code> is '+posOf(s,x,i)+'. <code>contains</code> is just <code>indexOf(x) >= 0</code> with a clearer name.'};},
        tip:"Case-sensitive: <code>\"Hello\".contains(\"hello\")</code> is false. Lower-case both sides first if you need a loose match.",iv:"Implemented as indexOf(s) >= 0. Takes a CharSequence, so a StringBuilder works too."},
      {c:"search",n:"startsWith(String)",sig:"boolean startsWith(String prefix)",s:"Hello, World",decl:"boolean b",args:[["prefix","String","Hell"]],run:(s,[x])=>{const ok=s.startsWith(x);return{r:ok,t:"boolean",hl:ok?range(0,x.length):range(0,Math.min(x.length,s.length),"cut"),why:ok?'<b>true</b>: the first '+plural(x.length,"character")+' are exactly <code>'+E(lit(x))+'</code>.':'<b>false</b>: the text does not begin with <code>'+E(lit(x))+'</code> (the first '+Math.min(x.length,s.length)+' characters are marked).'};},
        tip:'Every String starts with <code>""</code>: <code>s.startsWith("")</code> is always true.',iv:"Good for URL schemes and file prefixes; startsWith(prefix, offset) checks from a given index."},
      {c:"search",n:"endsWith(String)",sig:"boolean endsWith(String suffix)",s:"report.pdf",decl:"boolean b",args:[["suffix","String",".pdf"]],run:(s,[x])=>{const ok=s.endsWith(x);return{r:ok,t:"boolean",hl:ok?range(s.length-x.length,s.length):range(Math.max(0,s.length-x.length),s.length,"cut"),why:ok?'<b>true</b>: the last '+plural(x.length,"character")+' are exactly <code>'+E(lit(x))+'</code>.':'<b>false</b>: the text does not end with <code>'+E(lit(x))+'</code>.'};},
        tip:"The usual file-type check. Combine with <code>toLowerCase()</code> so <code>.PDF</code> also matches.",iv:"Equivalent to s.startsWith(suffix, s.length() - suffix.length())."},
      {c:"search",n:"matches(String)",sig:"boolean matches(String regex)",s:"2026-10-25",decl:"boolean b",args:[["regex","String","\\\\d{4}-\\\\d{2}-\\\\d{2}"]],run:(s,[re])=>{let rx;try{rx=new RegExp("^(?:"+re+")$");}catch(e){throw new JavaEx("PatternSyntaxException",e.message);}const ok=rx.test(s);return{r:ok,t:"boolean",hl:ok?range(0,s.length):[],why:ok?'<b>true</b>: the <b>whole</b> text fits the pattern (<code>\\d</code> is one digit, <code>{4}</code> means four of them).':'<b>false</b>: <code>matches</code> tests the <b>entire</b> String, as if the pattern were wrapped in <code>^…$</code>. A partial match is not enough.'};},
        tip:'In a Java literal a regex backslash is doubled: <code>"\\\\d"</code> is the regex <code>\\d</code>. A single <code>"\\d"</code> is a compile error.',iv:"matches() = whole String; find() on a Matcher = anywhere inside. Regex is a later lesson."},
      /* ---- extract & split ---- */
      {c:"extract",n:"substring(int)",sig:"String substring(int beginIndex)",s:"Hello, World",decl:"String t",args:[["beginIndex","int","7"]],run:(s,[b])=>{idx(s,b,true);const o=s.slice(b);return{r:lit(o),t:"String",out:o,hl:range(b,s.length),why:'Keeps everything from index <b>'+b+'</b> to the end: '+plural(o.length,"character")+'. The result is a '+NEW+'; <code>s</code> is untouched.'};},
        err:(s,[b])=>'<b>'+b+'</b> is outside 0 to '+s.length+'. Java throws; the message names the bad range.',
        tip:'<code>substring(s.length())</code> is legal and gives <code>""</code>; one more throws.',iv:"Since Java 7u6 substring copies the characters: the old shared-array memory leak is gone."},
      {c:"extract",n:"substring(int, int)",sig:"String substring(int beginIndex, int endIndex)",s:"Hello, World",decl:"String t",args:[["beginIndex","int","0"],["endIndex","int","5"]],run:(s,[b,e])=>{if(!Number.isInteger(b)||!Number.isInteger(e)||b<0||e>s.length||b>e)throw new JavaEx("StringIndexOutOfBoundsException","Range ["+b+", "+e+") out of bounds for length "+s.length);const o=s.slice(b,e);return{r:lit(o),t:"String",out:o,hl:range(b,e),why:'From index <b>'+b+'</b> up to but <b>not including</b> '+e+': characters '+b+'–'+(e-1)+', which is <code>end - begin</code> = <b>'+plural(e-b,"character")+'</b>.'+(e-b===0?' Equal indexes give <code>""</code>.':'')};},
        err:(s,[b,e])=>'Needs 0 ≤ begin ≤ end ≤ length ('+s.length+'). Here begin = '+b+', end = '+e+'.',
        tip:"<b>end is excluded.</b> The length of the result is always end − begin, which is the whole reason for the convention.",iv:'"Hello".substring(1, 3) is "el". Half-open ranges [begin, end) are used everywhere in Java: arrays, lists, streams.'},
      {c:"extract",n:"split(String)",sig:"String[] split(String regex)",s:"a,b,,c,,",decl:"String[] parts",args:[["regex","String",","]],run:(s,[re])=>{const a=jsplit(s,re,0);return{r:jarr(a),t:"String[]",list:a,why:'Cuts at every match of the regex <code>'+E(lit(re))+'</code>: <b>'+plural(a.length,"piece")+'</b>. Empty pieces in the <b>middle</b> are kept; empty pieces at the <b>end</b> are thrown away.'};},
        tip:'The argument is a <b>regex</b>: <code>split(".")</code> gives an empty array and <code>split("|")</code> splits between every character. Escape them: <code>split("\\\\.")</code>, <code>split("\\\\|")</code>.',iv:"Trailing empty strings are removed when the limit is 0 (the one-argument form)."},
      {c:"extract",n:"split(String, int)",sig:"String[] split(String regex, int limit)",s:"a,b,,c,,",decl:"String[] parts",args:[["regex","String",","],["limit","int","-1"]],run:(s,[re,l])=>{const a=jsplit(s,re,l);return{r:jarr(a),t:"String[]",list:a,why:(l<0?'A <b>negative</b> limit keeps every piece, including the empty ones at the end: ':l===0?'Limit 0 behaves like the one-argument form (trailing empties dropped): ':'Limit <b>'+l+'</b> stops after '+(l-1)+' cut'+(l===2?"":"s")+', so the last piece holds the rest of the text: ')+'<b>'+plural(a.length,"piece")+'</b>.'};},
        tip:'<code>line.split(",", 2)</code> is the way to cut "key,value" at the first comma only.',iv:"limit > 0: at most limit pieces. limit = 0: trailing empties removed. limit < 0: everything kept."},
      {c:"extract",n:"lines()",sig:"Stream<String> lines()",since:11,s:"one\\ntwo\\nthree\\n",decl:"List<String> ls",code:(s,call)=>"List<String> ls = "+call+".toList();",args:[],run:s=>{const a=jlines(s);return{r:jarr(a),t:"Stream<String>",list:a,why:'Splits at <code>\\n</code>, <code>\\r</code> or <code>\\r\\n</code>: <b>'+plural(a.length,"line")+'</b>. A final line terminator does not create an empty last line. It returns a <b>Stream</b>, so finish with <code>.toList()</code>, <code>.count()</code> or <code>.forEach(…)</code>.'};},
        tip:'Prefer <code>lines()</code> to <code>split("\\n")</code>: it handles Windows <code>\\r\\n</code> endings too.',iv:"Lazy: a huge text is not cut into pieces until the stream is consumed."},
      /* ---- transform ---- */
      {c:"transform",n:"toUpperCase()",sig:"String toUpperCase()",s:"Hello, World 42",decl:"String t",args:[],run:s=>{const o=s.toUpperCase(),{ch,why}=caseWhy(s,o,true);return{r:lit(o),t:"String",out:o,hl:ch.map(i=>[i,i+1,"chg"]),why};},
        tip:"<code>s.toUpperCase();</code> on its own does nothing visible: you must keep the result, <code>s = s.toUpperCase();</code>.",iv:"Locale matters: in Turkish \"i\".toUpperCase() is İ. Use toUpperCase(Locale.ROOT) for protocol strings."},
      {c:"transform",n:"toLowerCase()",sig:"String toLowerCase()",s:"Hello, World 42",decl:"String t",args:[],run:s=>{const o=s.toLowerCase(),{ch,why}=caseWhy(s,o,false);return{r:lit(o),t:"String",out:o,hl:ch.map(i=>[i,i+1,"chg"]),why};},
        tip:"Normalise e-mail addresses and commands with <code>toLowerCase()</code> before comparing them.",iv:"Equivalent to toLowerCase(Locale.getDefault()); pass Locale.ROOT when the text is not human language."},
      {c:"transform",n:"trim()",sig:"String trim()",s:"  java \\t",decl:"String t",args:[],run:s=>{const o=jtrim(s);let a=0,b=s.length;while(a<b&&s.charCodeAt(a)<=32)a++;while(b>a&&s.charCodeAt(b-1)<=32)b--;return{r:lit(o),t:"String",out:o,hl:[[0,a,"cut"],[b,s.length,"cut"]],why:'Removes every character with a code ≤ 32 (space, tab, newline…) from <b>both ends</b>: '+plural(s.length-o.length,"character")+' cut, nothing inside is touched.'+(s.length===o.length?' Nothing to cut here, so Java returns <code>s</code> itself.':'')};},
        tip:"<code>trim()</code> only knows ASCII whitespace. A non-breaking space (U+00A0) or an em space survives it; see <code>strip()</code>.",iv:"trim() is from Java 1.0 and cuts codes ≤ U+0020; strip() (Java 11) uses Character.isWhitespace, so it understands Unicode."},
      {c:"transform",n:"strip()",sig:"String strip()",since:11,s:"\\u2003 java \\u2003",decl:"String t",args:[],run:s=>{const o=jstrip(s);let a=0,b=s.length;while(a<b&&jws(s.charCodeAt(a)))a++;while(b>a&&jws(s.charCodeAt(b-1)))b--;return{r:lit(o),t:"String",out:o,hl:[[0,a,"cut"],[b,s.length,"cut"]],why:'Removes <b>Unicode</b> whitespace (anything <code>Character.isWhitespace</code> says yes to) from both ends: '+plural(s.length-o.length,"character")+' cut. <code>\\u2003</code> is an em space; <code>trim()</code> would have left it.'};},
        tip:"Use <code>strip()</code> for user input from the web, where exotic spaces are common.",iv:"Added in Java 11 with stripLeading(), stripTrailing() and isBlank()."},
      {c:"transform",n:"stripLeading()",sig:"String stripLeading()",since:11,s:"   java   ",decl:"String t",args:[],run:s=>{let a=0;while(a<s.length&&jws(s.charCodeAt(a)))a++;const o=s.slice(a);return{r:lit(o),t:"String",out:o,hl:[[0,a,"cut"]],why:'Only the <b>left</b> side is cleaned: '+plural(a,"character")+' removed, the trailing spaces stay (the result still ends with '+plural(o.length-o.replace(/\s+$/,"").length,"space")+').'};},
        tip:"Handy when indentation carries no meaning but trailing spaces do (fixed-width records).",iv:"The pair stripLeading / stripTrailing replaces the old regex idiom replaceAll(\"^\\\\s+\", \"\")."},
      {c:"transform",n:"stripTrailing()",sig:"String stripTrailing()",since:11,s:"   java   ",decl:"String t",args:[],run:s=>{let b=s.length;while(b>0&&jws(s.charCodeAt(b-1)))b--;const o=s.slice(0,b);return{r:lit(o),t:"String",out:o,hl:[[b,s.length,"cut"]],why:'Only the <b>right</b> side is cleaned: '+plural(s.length-b,"character")+' removed, the leading spaces stay.'};},
        tip:"Lines read from a file often carry trailing spaces or a \\r; this is the clean way to drop them.",iv:"Like strip(), it is Unicode-aware, unlike trim()."},
      {c:"transform",n:"replace(char, char)",sig:"String replace(char oldChar, char newChar)",s:"Hello, World",decl:"String t",args:[["oldChar","char","l"],["newChar","char","L"]],run:(s,[a,b])=>{const hits=[];for(let i=0;i<s.length;i++)if(s[i]===a)hits.push(i);const o=s.split(a).join(b);return{r:lit(o),t:"String",out:o,hl:hits.map(i=>[i,i+1,"chg"]),why:hits.length?'<b>Every</b> <code>\''+E(v(a))+'\'</code> ('+hits.length+' of them) became <code>\''+E(v(b))+'\'</code>. Plain characters, no regex. The result is a '+NEW+'.':'<code>\''+E(v(a))+'\'</code> does not occur, so nothing changes and Java returns <code>s</code> itself.'};},
        tip:"A char literal uses single quotes and holds exactly one character: <code>'l'</code>. <code>\"l\"</code> would call the CharSequence overload.",iv:"replace replaces all occurrences; the name is misleading. For the first one only, use replaceFirst (regex)."},
      {c:"transform",n:"replace(CharSequence, CharSequence)",sig:"String replace(CharSequence target, CharSequence replacement)",s:"Hello, World",decl:"String t",args:[["target","String","World"],["replacement","String","Java"]],run:(s,[a,b])=>{const hits=[];if(a!==""){let i=s.indexOf(a);while(i>=0){hits.push(i);i=s.indexOf(a,i+a.length);}}const o=a===""?b+s.split("").map(c=>c+b).join(""):s.split(a).join(b);return{r:lit(o),t:"String",out:o,hl:hits.map(i=>[i,i+a.length,"chg"]),why:a===""?'An empty target matches <b>between every character</b>, so the replacement is inserted everywhere.':hits.length?'<b>'+plural(hits.length,"occurrence")+'</b> of <code>'+E(lit(a))+'</code> replaced, left to right, as <b>plain text</b> (no regex: a dot is just a dot).':'<code>'+E(lit(a))+'</code> is not in the text, so nothing changes and Java returns <code>s</code> itself.'};},
        tip:"This is the one to use for literal text. <code>replaceAll</code> is for patterns.",iv:"replace() is the safe choice with user-supplied text; replaceAll() would treat $ and \\ in the replacement specially."},
      {c:"transform",n:"replaceAll(String, String)",sig:"String replaceAll(String regex, String replacement)",s:"a1b22c333",decl:"String t",args:[["regex","String","[0-9]+"],["replacement","String","#"]],run:(s,[re,rep])=>{let rx;try{rx=new RegExp(re,"g");}catch(e){throw new JavaEx("PatternSyntaxException",e.message);}const hits=[];let m;while((m=rx.exec(s))){hits.push([m.index,m.index+m[0].length,"chg"]);if(m[0]==="")rx.lastIndex++;}rx.lastIndex=0;const o=jrepl(s,rx,rep);return{r:lit(o),t:"String",out:o,hl:hits,why:'The regex <code>'+E(lit(re))+'</code> matched <b>'+plural(hits.length,"time")+'</b> (marked); each match became <code>'+E(lit(rep))+'</code>. <code>[0-9]+</code> means "one or more digits", so a run of digits is one match.'};},
        tip:"In the replacement, <code>$1</code> inserts a captured group and <code>\\</code> escapes. Use <code>Matcher.quoteReplacement</code> for arbitrary text.",iv:"replaceAll compiles the regex on every call; in a hot loop, precompile a Pattern."},
      {c:"transform",n:"replaceFirst(String, String)",sig:"String replaceFirst(String regex, String replacement)",s:"a1b22c333",decl:"String t",args:[["regex","String","[0-9]+"],["replacement","String","#"]],run:(s,[re,rep])=>{let rx;try{rx=new RegExp(re);}catch(e){throw new JavaEx("PatternSyntaxException",e.message);}const m=rx.exec(s);const o=jrepl(s,rx,rep);return{r:lit(o),t:"String",out:o,hl:m?[[m.index,m.index+m[0].length,"chg"]]:[],why:m?'Only the <b>first</b> match (at index '+m.index+') is replaced; the later ones are left alone.':'No match, so the text is returned unchanged.'};},
        tip:"Same regex rules as <code>replaceAll</code>; only the count differs.",iv:"There is no replaceLast; use lastIndexOf + substring, or a regex with a lookahead."},
      {c:"transform",n:"repeat(int)",sig:"String repeat(int count)",since:11,s:"ab",decl:"String t",args:[["count","int","3"]],run:(s,[n])=>{if(n<0)throw new JavaEx("IllegalArgumentException","count is negative: "+n);const o=s.repeat(n);return{r:lit(o),t:"String",out:o,hl:range(0,s.length),why:'The text is copied <b>'+n+'</b> time'+(n===1?"":"s")+' into one '+NEW+' of length '+s.length+' × '+n+' = <b>'+o.length+'</b>.'+(n===0?' Zero copies give <code>""</code>.':'')};},
        err:(s,[n])=>'A negative count makes no sense, so Java throws IllegalArgumentException.',
        tip:'Draw a rule: <code>"-".repeat(40)</code>. Before Java 11 people wrote a loop with StringBuilder.',iv:"repeat(0) is \"\"; repeat(1) returns s itself."},
      {c:"transform",n:"concat(String)",sig:"String concat(String str)",s:"Hello",decl:"String t",args:[["str","String",", World"]],run:(s,[x])=>{const o=s+x;return{r:lit(o),t:"String",out:o,hl:range(0,s.length),why:'Glues <code>'+E(lit(x))+'</code> onto the end: a '+NEW+' of length '+s.length+' + '+x.length+' = <b>'+o.length+'</b>. Exactly what <code>s + str</code> does.'+(x===""?' Appending <code>""</code> returns <code>s</code> itself.':'')};},
        tip:"<code>s + null</code> gives <code>\"snull\"</code>, but <code>s.concat(null)</code> throws NullPointerException.",iv:"Both + and concat create a new object. Many joins in a loop: use StringBuilder (next lesson)."},
      {c:"transform",n:"indent(int)",sig:"String indent(int n)",since:12,s:"a\\n  b",decl:"String t",args:[["n","int","2"]],run:(s,[n])=>{if(s==="")return{r:'""',t:"String",out:"",why:'The empty String stays empty.'};const ls=jlines(s).map(l=>n>0?" ".repeat(n)+l:l.replace(new RegExp("^\\s{0,"+(-n)+"}"),""));const o=ls.map(l=>l+"\n").join("");return{r:lit(o),t:"String",out:o,why:(n>0?'Adds <b>'+plural(n,"space")+'</b> to the start of <b>every</b> line':n<0?'Removes up to <b>'+(-n)+'</b> leading whitespace characters from every line':'Changes no indentation')+', normalises line endings to <code>\\n</code> and makes sure the text ends with one: '+plural(ls.length,"line")+'.'};},
        tip:"Useful for printing nested structures; <code>stripIndent()</code> (Java 15) does the opposite for text blocks.",iv:"Lines are found with lines(), so \\r\\n is handled."},
      {c:"transform",n:"formatted(Object...)",sig:"String formatted(Object... args)",since:15,s:"Total: %,d items",decl:"String t",args:[["arg","any","1234567"]],run:(s,[a])=>{const o=fmt(s,a);return{r:lit(o),t:"String",out:o,why:'<code>s</code> is the <b>format</b>; each <code>%</code> code is replaced by the next argument. <code>%d</code> = whole number, <code>%s</code> = any value as text, <code>%.2f</code> = 2 decimals, <code>,</code> = thousands separators, a width such as <code>%8d</code> pads on the left, <code>%-8s</code> on the right.'};},
        tip:'<code>%d</code> with a String argument throws IllegalFormatConversionException at <b>run time</b>; the compiler cannot check format codes.',iv:"formatted(args) is the instance form of String.format(fmt, args), added in Java 15 for text blocks."},
      /* ---- compare ---- */
      {c:"compare",n:"equals(Object)",sig:"boolean equals(Object other)",s:"Hello, World",decl:"boolean b",args:[["other","String","hello, world"]],run:(s,[x])=>{let i=0;while(i<s.length&&i<x.length&&s[i]===x[i])i++;const ok=s===x;return{r:ok,t:"boolean",hl:ok?range(0,s.length):(i<s.length?range(i,i+1,"cut"):[]),why:ok?'<b>true</b>: same length and the same character at every index. Two different objects can be equal; that is the whole point of <code>equals</code>.':s.length!==x.length&&i===Math.min(s.length,x.length)?'<b>false</b>: the lengths differ ('+s.length+' vs '+x.length+').':'<b>false</b>: the first difference is at index <b>'+i+'</b>: <code>\''+E(v(s[i]))+'\'</code> vs <code>\''+E(v(x[i]))+'\'</code>. Case counts.'};},
        tip:'Put the literal first, <code>"yes".equals(input)</code>: it can never throw when <code>input</code> is null.',iv:"== compares references, equals compares characters (section 06). equals checks identity first, then length, then the bytes."},
      {c:"compare",n:"equalsIgnoreCase(String)",sig:"boolean equalsIgnoreCase(String other)",s:"Hello, World",decl:"boolean b",args:[["other","String","hello, world"]],run:(s,[x])=>{const a=foldS(s),b=foldS(x);let i=0;while(i<a.length&&i<b.length&&a[i]===b[i])i++;const ok=a===b;return{r:ok,t:"boolean",hl:ok?range(0,s.length):(i<s.length?range(i,i+1,"cut"):[]),why:ok?'<b>true</b>: with case ignored, every character matches'+(s!==x?' (they differ only in case)':'')+'.':s.length!==x.length?'<b>false</b>: the lengths differ ('+s.length+' vs '+x.length+').':'<b>false</b>: index <b>'+i+'</b> differs even with case ignored.'};},
        tip:"Use it for commands and answers (\"Yes\", \"YES\", \"yes\"), not for passwords.",iv:"Compares char by char with Character.toUpperCase then toLowerCase; no new Strings are created."},
      {c:"compare",n:"compareTo(String)",sig:"int compareTo(String other)",s:"Hello, World",decl:"int d",args:[["other","String","Help"]],run:(s,[x])=>{const d=jcompare(s,x);let i=0;while(i<s.length&&i<x.length&&s[i]===x[i])i++;return{r:d,t:"int",hl:i<s.length?range(i,i+1):[],why:d===0?'<b>0</b>: the Strings are equal.':i<s.length&&i<x.length?'The first difference is at index <b>'+i+'</b>: <code>\''+E(v(s[i]))+'\'</code> ('+s.charCodeAt(i)+') minus <code>\''+E(v(x[i]))+'\'</code> ('+x.charCodeAt(i)+') = <b>'+d+'</b>. Negative means <code>s</code> sorts <b>before</b> the other.':'One is a prefix of the other, so the answer is the length difference: '+s.length+' − '+x.length+' = <b>'+d+'</b>.'};},
        tip:"Only the <b>sign</b> is promised: negative, zero or positive. Never test <code>compareTo(x) == -1</code>.",iv:"This is the natural ordering used by sorted collections and Collections.sort: dictionary order by UTF-16 code, so uppercase (65–90) comes before lowercase (97–122)."},
      {c:"compare",n:"compareToIgnoreCase(String)",sig:"int compareToIgnoreCase(String other)",s:"apple",decl:"int d",args:[["other","String","Banana"]],run:(s,[x])=>{const d=jcompare(foldS(s),foldS(x));return{r:d,t:"int",why:d===0?'<b>0</b>: equal when case is ignored.':'With case folded away, '+E(lit(s))+' sorts <b>'+(d<0?"before":"after")+'</b> '+E(lit(x))+' ('+d+').'+(jcompare(s,x)*d<0?' Plain <code>compareTo</code> would say the opposite, because uppercase letters have smaller codes.':'')};},
        tip:"The right comparator for sorting names: <code>list.sort(String::compareToIgnoreCase)</code>, or <code>String.CASE_INSENSITIVE_ORDER</code>.",iv:"Same contract as compareTo: only the sign is meaningful."},
      {c:"compare",n:"intern()",sig:"String intern()",s:"car",decl:"String p",args:[],run:s=>({r:lit(s),t:"String",out:s,hl:range(0,s.length),why:'Returns the <b>pooled</b> String with this text: the same characters, but possibly a different object. For a literal, <code>s.intern() == s</code> is true; for <code>new String("car")</code> it is false, yet <code>new String("car").intern() == "car"</code> is true. The sticker book in section 04 shows it.'}),
        tip:"Rarely needed in application code; parsers use it to share millions of identical tokens.",iv:"Since Java 7 the pool lives on the heap and intern() adds the reference itself, it copies nothing."},
      /* ---- convert & static ---- */
      {c:"convert",n:"toCharArray()",sig:"char[] toCharArray()",s:"Java",decl:"char[] cs",args:[],run:s=>{const a=s.split("");return{r:jarr(a),t:"char[]",list:a,hl:range(0,s.length),why:'Copies the '+plural(s.length,"character")+' into a <b>fresh array</b>. You may change the array (<code>cs[0] = \'L\'</code>) and <code>s</code> stays <code>'+E(lit(s))+'</code>: the two never share storage.'};},
        tip:"The classic way to walk or sort characters: <code>Arrays.sort(cs)</code>, then <code>new String(cs)</code>.",iv:"O(n) copy each call; inside a loop, call it once before the loop."},
      {c:"convert",n:"chars()",sig:"IntStream chars()",s:"Java",decl:"int[] codes",code:(s,call)=>"int[] codes = "+call+".toArray();",args:[],run:s=>{const a=s.split("").map(c=>c.charCodeAt(0));return{r:jarr(a),t:"IntStream",list:a,hl:range(0,s.length),why:'A stream of the UTF-16 code units as <b>int</b>s: <code>\''+E(v(s[0]||"?"))+'\'</code> is '+(s.charCodeAt(0)||0)+'. Characters are numbers underneath; filter or count them with the stream API.'};},
        tip:'Count vowels: <code>s.chars().filter(c -> "aeiou".indexOf(c) >= 0).count()</code>.',iv:"chars() gives code units; codePoints() gives real Unicode characters (an emoji is one code point but two chars)."},
      {c:"convert",n:"getBytes()",sig:"byte[] getBytes()",s:"Hi \\u20B9",decl:"byte[] bs",args:[],run:s=>{const a=Array.from(enc.encode(s)).map(b=>b>127?b-256:b);return{r:jarr(a),t:"byte[]",list:a,hl:range(0,s.length),why:'Encodes the text in the default charset, <b>UTF-8</b> since Java 18: '+plural(s.length,"character")+' became <b>'+plural(a.length,"byte")+'</b>. ASCII letters take one byte each; <code>₹</code> takes three. Java bytes are signed, so values above 127 print as negatives.'};},
        tip:"Always say which charset when the bytes leave your program: <code>getBytes(StandardCharsets.UTF_8)</code>.",iv:"This is NOT the String's internal array: internally Java keeps Latin-1 (1 byte per char) or UTF-16 (2 bytes), chosen per String since Java 9 (compact strings)."},
      {c:"convert",n:"toString()",sig:"String toString()",s:"Java",decl:"String t",args:[],run:s=>({r:lit(s),t:"String",out:s,why:'Returns <b>this very object</b>, no copy: <code>s.toString() == s</code> is true. It exists so that every object, String included, can be printed.'}),
        tip:'<code>String.valueOf(obj)</code> is the null-safe way to print anything; <code>obj.toString()</code> throws on null.',iv:"Every class inherits toString from Object; String overrides it to return itself."},
      {c:"convert",n:"String.valueOf(int)",sig:"static String valueOf(int i)",st:true,s:"",decl:"String t",args:[["i","int","42"]],run:(s,[n])=>{const o=String(n);return{r:lit(o),t:"String",out:o,why:'Turns the number <b>'+n+'</b> into the text <code>'+E(lit(o))+'</code>: '+plural(o.length,"character")+'. There is an overload for every primitive and for Object. <code>"" + 42</code> does the same thing.'};},
        tip:"The opposite direction is <code>Integer.parseInt(\"42\")</code>, which throws NumberFormatException on bad input.",iv:"valueOf(Object) returns \"null\" for a null argument instead of throwing; valueOf(char[]) copies the array."},
      {c:"convert",n:"String.join(CharSequence, CharSequence...)",sig:"static String join(CharSequence delimiter, CharSequence... elements)",st:true,s:"",decl:"String t",args:[["delimiter","String",", "],["e1","String","red"],["e2","String","green"],["e3","String","blue"]],run:(s,[d,...xs])=>{const o=xs.join(d);return{r:lit(o),t:"String",out:o,why:'Puts <code>'+E(lit(d))+'</code> <b>between</b> the '+plural(xs.length,"element")+' (never at the ends): '+plural(xs.length-1,"separator")+'.'};},
        tip:"It also takes a List: <code>String.join(\", \", names)</code>. For a prefix/suffix or streams, use <code>Collectors.joining</code>.",iv:"Implemented with StringJoiner; one allocation for the result, no O(n²) concatenation."},
      {c:"convert",n:"String.format(String, Object...)",sig:"static String format(String format, Object... args)",st:true,s:"",decl:"String t",args:[["format","String","[%-6s] done %%"],["arg","any","Java"]],run:(s,[f,a])=>{const o=fmt(f,a);return{r:lit(o),t:"String",out:o,why:'Builds text from a <b>format</b> and arguments, like C\'s printf. <code>%-6s</code> = text padded to 6 columns on the right (<code>%6s</code> pads on the left); <code>%5.1f</code> = a number with 1 decimal in 5 columns; <code>%%</code> = a literal percent sign. <code>System.out.printf</code> uses exactly this. Try the argument <code>3.14159</code> with <code>%.2f</code>.'};},
        tip:"Each argument is matched in order; a missing argument throws MissingFormatArgumentException at run time.",iv:"Slower than concatenation (it parses the format every time); fine for output, avoid it in tight loops."}
    ];
    const CATS=[["inspect","Inspect"],["search","Search"],["extract","Extract & split"],["transform","Transform"],["compare","Compare"],["convert","Convert & static"]];
    host.classList.add("sm");
    host.innerHTML=head("String methods playground","Pick a method, change the text and the arguments, and read exactly what Java returns and why.",
      ["<b>"+M.length+" methods</b> in 6 groups","every method returns a <b>new</b> object: <code>s</code> never changes","the text is a Java literal: <code>\\n</code> <code>\\t</code> <code>\\u2003</code> work","← → keys step through the methods"])+
      '<div class="vbody"><div class="sm-top"><label class="sm-s"><span>String s = "</span><input id="smS" spellcheck="false" autocomplete="off" aria-label="The String s (body of a Java literal)"><span>";</span></label>'+
      '<div class="sm-presets" role="group" aria-label="Sample texts"><button type="button" class="chip" data-p="Hello, World">Hello, World</button><button type="button" class="chip" data-p="  java \\t">spaces</button><button type="button" class="chip" data-p="a,b,,c,,">a,b,,c,,</button><button type="button" class="chip" data-p="Mississippi">Mississippi</button><button type="button" class="chip" data-p="">empty ""</button><button type="button" class="chip sm-auto on" data-p="*">method\'s own sample</button></div></div>'+
      '<div class="sm-grid"><div class="sm-side"><div class="sm-cats" role="tablist">'+CATS.map(([k,t])=>'<button type="button" class="sm-cat" role="tab" data-c="'+k+'">'+t+'<i>'+M.filter(m=>m.c===k).length+'</i></button>').join("")+'</div><div class="sm-list" role="listbox" aria-label="Methods"></div></div>'+
      '<div class="sm-main"><div class="sm-sig"><code></code><span class="sm-since"></span></div><div class="sm-args"></div><div class="sm-stage"></div><div class="an-code sm-code"></div><div class="msg sm-why" aria-live="polite"></div><div class="sm-tips"><div><b>Watch out</b><span class="sm-tip"></span></div><div><b>Interview</b><span class="sm-iv"></span></div></div>'+
      '<div class="ctrl"><button type="button" class="btn" data-a="back">← Previous</button><button type="button" class="btn" data-a="next">Next method →</button><button type="button" class="btn ghost" data-a="play">▶ Tour all</button><span class="sm-count" aria-live="polite"></span></div></div></div></div>';
    const sIn=$("#smS",host),list=$(".sm-list",host),args=$(".sm-args",host),stage=$(".sm-stage",host),code=$(".sm-code",host),why=$(".sm-why",host),count=$(".sm-count",host);
    let cur=M.findIndex(m=>m.n==="indexOf(String)"),auto=true,timer=null,seen=new Set();
    try{seen=new Set(JSON.parse(store.get("js1-sm-seen")||"[]"));}catch(e){seen=new Set();}
    const cat=()=>M[cur].c;
    const drawList=()=>{const k=cat();$$(".sm-cat",host).forEach(b=>{b.classList.toggle("on",b.dataset.c===k);b.setAttribute("aria-selected",b.dataset.c===k);});
      list.innerHTML=M.map((m,i)=>m.c!==k?"":'<button type="button" class="sm-m'+(i===cur?" on":"")+(seen.has(m.n)?" seen":"")+'" role="option" aria-selected="'+(i===cur)+'" data-m="'+i+'">'+E(m.n)+(m.since?'<i>'+m.since+'+</i>':'')+'</button>').join("");
      count.textContent="Explored "+M.filter(m=>seen.has(m.n)).length+" / "+M.length;};
    const drawArgs=m=>{args.innerHTML=m.args.length?m.args.map((a,i)=>'<label class="sm-arg"><span>'+E(a[0])+'<i>'+E(a[1]==="any"?"Object":a[1])+'</i></span>'+(a[1]==="char"?"'":a[1]==="String"?'"':'')+'<input class="arg" data-i="'+i+'" data-t="'+a[1]+'" value="'+E(a[2])+'" spellcheck="false" autocomplete="off" aria-label="'+E(a[0])+'" '+(a[1]==="char"?'maxlength="6" size="3"':a[1]==="int"?'inputmode="numeric" size="5"':'size="'+Math.max(6,Math.min(24,a[2].length+2))+'"')+'>'+(a[1]==="char"?"'":a[1]==="String"?'"':'')+'</label>').join(""):'<span class="sm-noarg">no arguments</span>';};
    /* parse the inputs the way javac would: ints must be whole numbers, chars exactly one character, Strings are literal bodies */
    const parseArg=(t,raw)=>{
      if(t==="int"){if(!/^-?\d+$/.test(raw.trim()))throw new JavaEx("compile error","incompatible types: "+(raw.trim()===""?"missing argument":"String cannot be converted to int"));return{v:+raw.trim(),src:raw.trim()};}
      if(t==="char"){const c=unesc(raw);if(c.length!==1)throw new JavaEx("compile error",c.length===0?"empty character literal":"unclosed character literal: a char holds exactly one character");return{v:c,src:"'"+(c==="'"?"\\'":show(c).replace(/\\"/g,'"'))+"'"};}
      if(t==="any"){const a=anyArg(raw);return{v:a,src:a.src};}
      const sv=unesc(raw);return{v:sv,src:lit(sv)};};
    const readArgs=m=>$$("input.arg",args).map(x=>parseArg(x.dataset.t,x.value));
    const calc=(i,sRaw,argVals)=>{const m=M[i];const s=unesc(sRaw);return m.run(s,argVals);};
    const stateOf=(hl,n)=>{const st=new Array(n).fill("");(hl||[]).forEach(([a,b,k])=>{for(let i=Math.max(0,a);i<Math.min(n,b);i++)st[i]=k;});return st;};
    const row=(label,s,st)=>'<div class="row"><span class="lb">'+label+'</span>'+(s.length?cells(s.split("").map((ch,k)=>({ch:ch==="\n"?"⏎":ch==="\t"?"⇥":ch==="\r"?"␍":ch,s:(st&&st[k])||""}))):'<div class="rq-empty">empty: length 0</div>')+"</div>";
    const render=()=>{const m=M[cur];
      $(".sm-sig code",host).innerHTML=hl(m.sig);$(".sm-since",host).textContent=m.since?"Java "+m.since+"+":"Java 1.0";$(".sm-since",host).classList.toggle("sm-old",!m.since);
      $(".sm-tip",host).innerHTML=m.tip;$(".sm-iv",host).innerHTML=m.iv;
      let s="",av,res,err=null,srcs=[];
      try{s=unesc(sIn.value);av=readArgs(m);srcs=av.map(a=>a.src);res=m.run(s,av.map(a=>a.v));}catch(e){err=e;}
      const call=(m.st?"String":"s")+"."+m.n.split("(")[0]+"("+srcs.join(", ")+")";
      let html="";
      if(!m.st)html+=row("s",s,res?stateOf(res.hl,s.length):null);
      if(err){html+='<div class="sm-ret bad"><b>'+E(err.t||"Error")+'</b>'+(err.message?': '+E(err.message):'')+'</div>';
        why.innerHTML=(err.t==="compile error"?'<b>Does not compile.</b> ':'<b>Throws at run time.</b> ')+(m.err&&err.t!=="compile error"?m.err(s,av.map(a=>a.v)):E(err.message||""))+(err.t==="compile error"?'':' Nothing is returned; the program stops here unless the exception is caught.');}
      else{const t=res.t,isStr=res.out!=null;
        html+='<div class="sm-ret"><span class="sm-arrow">'+E(call)+' →</span><b class="sm-val">'+E(String(res.r))+'</b><span class="sm-type">'+E(t)+'</span>'+(isStr?NEW:res.list?'<span class="sm-new">new '+E(t)+'</span>':'<span class="sm-prim">a value, not a String</span>')+'</div>';
        if(isStr)html+=row("result",res.out,stateOf([[0,res.out.length,"new"]],res.out.length));
        else if(res.list)html+='<div class="sm-pieces">'+(res.list.length?res.list.map((p,i)=>'<span><i>'+i+'</i>'+(p===""?'<em>""</em>':E(String(p).replace(/ /g,"␣")))+'</span>').join(""):'<em class="sm-noarg">length 0</em>')+'</div>';
        if(!m.st&&isStr)html+='<div class="sm-still">s is still <code>'+E(lit(s))+'</code>: the method made a new object and left the old one alone.</div>';
        why.innerHTML=res.why;}
      stage.innerHTML=html;
      const lines=[];if(!m.st)lines.push('String s = '+lit(s)+';');
      lines.push(err?(m.decl+" = "+call+";   // "+(err.t||"Error")):m.code?m.code(s,call)+"   // "+String(res.r):m.decl+" = "+call+";   // "+String(res.r));
      code.innerHTML=lines.map((l,i)=>'<div class="'+(i===lines.length-1?"cur":"")+'">'+hl(l)+"</div>").join("");
      if(!still)$$(".c.read,.c.chg,.c.cut",stage).forEach((c,i)=>c.animate([{transform:"translateY(6px)",opacity:.2},{transform:"none",opacity:1}],{duration:260,delay:Math.min(i,16)*22,easing:"ease-out"}));
      $('[data-a="back"]',host).disabled=cur===0;$('[data-a="next"]',host).disabled=cur===M.length-1;};
    const pick=(i,fromUser)=>{cur=Math.max(0,Math.min(M.length-1,i));const m=M[cur];
      if(auto&&!m.st)sIn.value=m.s;
      if(fromUser!==false&&!seen.has(m.n)){seen.add(m.n);store.set("js1-sm-seen",JSON.stringify([...seen]));}
      drawList();drawArgs(m);render();const on=$(".sm-m.on",list);if(on&&on.scrollIntoView&&fromUser==="key")on.scrollIntoView({block:"nearest"});};
    const stop=()=>{if(timer){clearInterval(timer);timer=null;}$('[data-a="play"]',host).textContent="▶ Tour all";};
    host.addEventListener("click",e=>{const c=e.target.closest(".sm-cat");if(c){stop();pick(M.findIndex(m=>m.c===c.dataset.c));return;}
      const b=e.target.closest(".sm-m");if(b){stop();pick(+b.dataset.m);return;}
      const p=e.target.closest("[data-p]");if(p){stop();$$("[data-p]",host).forEach(x=>x.classList.toggle("on",x===p));if(p.dataset.p==="*"){auto=true;sIn.value=M[cur].s;}else{auto=false;sIn.value=p.dataset.p;}render();return;}
      const a=e.target.closest("[data-a]");if(!a)return;
      if(a.dataset.a==="back"){stop();pick(cur-1,"key");}else if(a.dataset.a==="next"){stop();pick(cur+1,"key");}
      else if(a.dataset.a==="play"){if(timer){stop();return;}if(cur===M.length-1)pick(0,"key");a.textContent="⏸ Stop";timer=setInterval(()=>{if(cur>=M.length-1)stop();else pick(cur+1,"key");},still?6000:3200);}});
    sIn.addEventListener("input",()=>{auto=false;$$("[data-p]",host).forEach(x=>x.classList.remove("on"));stop();render();});
    args.addEventListener("input",()=>{stop();render();});
    pick(cur,false);
    window.SMX={M,calc,unesc,lit,parseArg,pick:i=>pick(typeof i==="number"?i:M.findIndex(m=>m.n===i))};
  })();
})();
